import{_ as i,l,o as e,c as s,v as t,p as n,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"冲洗与表面活性剂","description":"","frontmatter":{"title":"冲洗与表面活性剂","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/rinse-surfactant.md","filePath":"litho/rinse-surfactant.md","lastUpdated":1789023840000}'),c={name:"litho/rinse-surfactant.md"};function _(m,a,u,f,E,A){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="冲洗与表面活性剂" tabindex="-1">冲洗与表面活性剂 <a class="header-anchor" href="#冲洗与表面活性剂" aria-label="Permalink to &quot;冲洗与表面活性剂&quot;">​</a></h1><div class="epigraph"><p>冲洗要结束溶解、带走盐，还要决定干燥时缝里还剩什么液体。表面活性剂改接触角，是倒塌课的液体旋钮。</p><footer>—— 对照显影后 DI 水漂洗与 surfactant rinse 公开实践</footer></div><p><a href="/litho/tmah-developer">上一课</a>停在碱液里。缺口是换成水（或含表面活性剂的漂洗）：停显影、降离子、为干燥做准备。主干 <a href="/litho/pattern-collapse">图形倒塌</a> 已写毛细力；本课把轨道上的冲洗接到那一课，不重推弯月面公式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>碱不冲干净，会继续咬、会留盐晶体。纯水冲洗的表面张力高，高深宽比线在干燥时对拉。表面活性剂降低 \\(\\gamma\\)、改接触角，减轻倒塌，但可能留有机残、改后续刻蚀。把倒塌只写成「胶太高」，会漏掉这瓶漂洗液。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>多步：DI 水喷淋或 puddle，可选表面活性剂漂，再甩干。时间与转速影响残留液膜。超临界 CO₂ 干燥是另一条资本路径，本课只点名，不展开设备。</p>',7)),(e(),n(p,null,{default:r(()=>[h(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20ALK%5B%22TMAH%20puddle%22%5D%20--%3E%20DI%5B%22DI%20%E5%86%B2%E6%B4%97%22%5D%0A%20%20DI%20--%3E%20SURF%5B%22%E5%8F%AF%E9%80%89%E8%A1%A8%E9%9D%A2%E6%B4%BB%E6%80%A7%E5%89%82%22%5D%0A%20%20SURF%20--%3E%20DRY%5B%22%E7%94%A9%E5%B9%B2%20%2F%20%E6%AF%9B%E7%BB%86%22%5D%0A%20%20DRY%20--%3E%20COL%5B%22%E5%80%92%E5%A1%8C%E9%A3%8E%E9%99%A9%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><span class="marginnote">表面活性剂配方是供应商黑盒。换胶常要换漂洗，缺陷与倒塌窗口一起动。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>冲洗把溶解产物浓度打下去，溶解反应停。干燥时若缝中仍是高 \\(\\gamma\\) 液体，毛细压差最大。表面活性剂吸附在胶与水界面，降 \\(\\gamma\\)，也改变是否铺展进缝。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不替代倒塌课的力学。下一课专写倒塌抑制的其他手段（深宽比、硬化、溶剂）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>冲洗停显影，并设定干燥液体。</li><li>表面活性剂是倒塌–残留的权衡。</li><li>出处：倒塌课；轨道漂洗通识。</li></ul>',7))])}const T=i(c,[["render",_]]);export{D as __pageData,T as default};
